export interface JourneyPreferences {
  readonly maximumCost: number;
  readonly providers: readonly string[];
}

export interface PreferenceGateway {
  save(preferences: JourneyPreferences): Promise<void>;
}

export interface Notifier {
  success(message: string): void;
  error(message: string): void;
}

export interface PreferenceSnapshot {
  readonly maximumCost: number | null;
  readonly providers: string[];
}

export class PreferenceForm {
  private maximumCost: number | null = null;
  private providers: string[] = [];

  public constructor(
    private readonly gateway: PreferenceGateway,
    private readonly notifier: Notifier,
    private readonly navigate: () => void,
  ) {}

  public setMaximumCost(value: number | null): void {
    this.maximumCost = value;
  }

  public setProviders(values: string[]): void {
    if (values.some(value => typeof value !== 'string' || value.trim() === '')) {
      throw new TypeError('Providers must be non-empty strings');
    }
    this.providers = values;
  }

  public get snapshot(): PreferenceSnapshot {
    return { maximumCost: this.maximumCost, providers: [...this.providers] };
  }

  public async submit(): Promise<boolean> {
    if (this.maximumCost === null || !Number.isFinite(this.maximumCost) || this.maximumCost <= 0) {
      this.notifier.error('A positive maximum cost is required.');
      return false;
    }
    const preferences: JourneyPreferences = {
      maximumCost: this.maximumCost,
      providers: [...this.providers],
    };
    try {
      await this.gateway.save(preferences);
      this.notifier.success('Preferences saved.');
      this.navigate();
      return true;
    } catch {
      this.notifier.error('Could not save preferences.');
      return false;
    }
  }
}

