import { PreferenceForm } from './solution';
import type { JourneyPreferences, PreferenceGateway, Notifier, PreferenceSnapshot } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

async function run(): Promise<void> {
  const calls: string[] = [];
  const saved: JourneyPreferences[] = [];
  const gateway = {
    async save(value: JourneyPreferences): Promise<void> {
      calls.push('save');
      saved.push(value);
    },
  } as PreferenceGateway;
  const notifier = {
    success(message: string): void { calls.push(`success:${message}`); },
    error(message: string): void { calls.push(`error:${message}`); },
  } as Notifier;
  const form = new PreferenceForm(gateway, notifier, () => { calls.push('navigate'); });

  const initialA = form.snapshot;
  const initialB = form.snapshot;
  equal(initialA.maximumCost, null, 'initial maximum cost');
  equal(initialA.providers.length, 0, 'initial providers');
  assert(initialA !== initialB, 'snapshot object must be fresh');
  assert(initialA.providers !== initialB.providers, 'snapshot providers must be fresh');

  form.setMaximumCost(25);
  const source = ['One', 'Two', 'One'];
  form.setProviders(source);
  source[0] = 'changed';
  const snapshot: PreferenceSnapshot = form.snapshot;
  equal(snapshot.maximumCost, 25, 'maximum cost stored');
  equal(snapshot.providers.join(','), 'One,Two,One', 'providers copied with order and duplicates');
  (snapshot.providers as string[])[1] = 'changed';
  equal(form.snapshot.providers.join(','), 'One,Two,One', 'snapshot mutation cannot affect form');
  equal(calls.length, 0, 'setters do not submit');

  for (const invalid of [['ok', ' '], ['ok', 3] as any]) {
    let threw = false;
    try { form.setProviders(invalid as any); } catch (error) { threw = error instanceof TypeError; }
    assert(threw, 'invalid provider must throw TypeError');
    equal(form.snapshot.providers.join(','), 'One,Two,One', 'rejected providers do not alter state');
  }

  for (const invalidCost of [null, 0, -1, Number.NaN, Infinity]) {
    form.setMaximumCost(invalidCost);
    const before = calls.length;
    equal(await form.submit(), false, `invalid submission ${String(invalidCost)}`);
    equal(calls.length, before + 1, 'invalid submission only notifies once');
    equal(calls[calls.length - 1], 'error:A positive maximum cost is required.', 'invalid message');
  }
  equal(saved.length, 0, 'invalid submissions never save');
  assert(!calls.includes('navigate'), 'invalid submissions never navigate');

  calls.length = 0;
  form.setMaximumCost(50);
  form.setProviders(['A', 'B']);
  equal(await form.submit(), true, 'successful submit result');
  equal(calls.join('|'), 'save|success:Preferences saved.|navigate', 'successful operation order');
  equal(saved.length, 1, 'save called exactly once');
  assert(saved[0] !== form.snapshot, 'saved object detached');
  assert(saved[0].providers !== form.snapshot.providers, 'saved providers detached');
  (saved[0].providers as string[])[0] = 'gateway mutation';
  equal(form.snapshot.providers.join(','), 'A,B', 'gateway argument mutation cannot affect form');

  const rejectingCalls: string[] = [];
  const rejectingGateway = {
    async save(value: JourneyPreferences): Promise<void> {
      rejectingCalls.push('save');
      (value.providers as string[]).push('mutated');
      throw new Error('failure');
    },
  } as PreferenceGateway;
  const rejectingNotifier = {
    success(message: string): void { rejectingCalls.push(`success:${message}`); },
    error(message: string): void { rejectingCalls.push(`error:${message}`); },
  } as Notifier;
  const rejectingForm = new PreferenceForm(rejectingGateway, rejectingNotifier, () => rejectingCalls.push('navigate'));
  rejectingForm.setMaximumCost(1);
  rejectingForm.setProviders(['safe']);
  equal(await rejectingForm.submit(), false, 'rejection returns false');
  equal(rejectingCalls.join('|'), 'save|error:Could not save preferences.', 'rejection behavior');
  equal(rejectingForm.snapshot.providers.join(','), 'safe', 'rejecting gateway cannot mutate state');
}

run().catch(error => { throw error; });

